export function distanceKm(a,b){if(!a||!b||a.length!==2||b.length!==2||![...a,...b].every(Number.isFinite)||Math.abs(a[0])>90||Math.abs(b[0])>90||Math.abs(a[1])>180||Math.abs(b[1])>180)return null;const r=x=>x*Math.PI/180,dl=r(b[0]-a[0]),dn=r(b[1]-a[1]),h=Math.sin(dl/2)**2+Math.cos(r(a[0]))*Math.cos(r(b[0]))*Math.sin(dn/2)**2;return 6371*2*Math.atan2(Math.sqrt(Math.min(1,h)),Math.sqrt(Math.max(0,1-h)));}
export function orderMatches(list,mode,origin,coordinates,available){const distance=m=>distanceKm(origin,coordinates?.[m.city.trim().toLocaleLowerCase()]);return [...list].sort((a,b)=>{let difference=0;if(mode==='distance'&&origin)difference=(distance(a)??Infinity)-(distance(b)??Infinity);if(mode==='price')difference=a.priceCents-b.priceCents;if(mode==='places')difference=available(b.id)-available(a.id);return (Number.isNaN(difference)?0:difference)||Date.parse(a.startsAt)-Date.parse(b.startsAt)||a.id.localeCompare(b.id);});}
